const PE_pts=(f,t0,t1,x0,x1,yc,k,n=120)=>{let p=[];for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n;p.push([x0+(x1-x0)*i/n,yc-k*f(t)])}return p};
