/* cycloconverter hump, worked example 1: |sin| of the supply conducted from alpha to pi in each half cycle */
const PE_hump=(th,al)=>{const h=((th%Math.PI)+Math.PI)%Math.PI;return h>=al?Math.abs(Math.sin(th)):0};
